test('the loop stops at maxItems even with more ready work', async () => {
  const repo = fakeRepo([
    workItem(1, 'a', ['task:ready', 'origin:schedule']),
    workItem(2, 'a', ['task:ready', 'origin:schedule']),
    workItem(3, 'a', ['task:ready', 'origin:schedule']),
  ]);
