      for (let t = Math.ceil(from / DAY) * DAY + 4 * HOUR + 3 * MIN; t < to; t += DAY) {
        if (t >= from) schedule(t, janitor);
      }
      for (;;) {
        queue.sort((a, b) => a.t - b.t || a.seq - b.seq);
        const ev = queue.shift();
        if (!ev || ev.t >= to) break;
        now = ev.t;
        ev.fn();
      }
