cat >> docs/tasks-dispatch/sim/scenarios.test.mjs <<'EOF'

// ---- S39 — the episode boundary must survive an episode that ended SILENTLY
// (F24). S32 races two executors WITHIN one episode; this races them ACROSS
// one. The roll and the `needs-human` park both end an episode without writing
// a comment, so unless the departing executor strikes its own claim, the next
// claimant loses to a dead one — the roll for a leash period, the park forever.
test('S39 a rolled item is claimable on its next anchor — the roll struck its claim', () => {
  const tasks = cast().filter((t) => t.id === 'tidy/tidy-issues');
  const sim = makeSim({ tasks }).seedSteadyState('2026-08-12T00:00Z');
  // The precondition declines all day: every anchor rolls, every roll ends an
  // episode, and each following day must still be claimable.
  sim.at('2026-08-12T00:00Z', ({ world }) => { world.issueTouchedAt = null; });
  sim.run('2026-08-12T00:00Z', '2026-08-15T00:00Z');

  const rolls = sim.log.filter((e) => e.kind === 'roll');
  assert.ok(rolls.length >= 2, `the item rolled on successive anchors (got ${rolls.length})`);
  assert.deepEqual(sim.log.filter((e) => e.kind === 'claim-lost'), [],
    'no claim may be lost to a previous episode\'s spent claim');
  // Every anchor got its verdict: a livelocked item would silently skip them.
  assert.equal(sim.log.filter((e) => e.kind === 'evaluate').length, rolls.length,
    'each roll is one evaluation — none was skipped waiting on a dead claim');
});

test('S39b a parked item a human re-queues is claimable at once — the park struck its claim', () => {
  const tasks = cast().filter((t) => t.id === 'basics/baselining');
  const sim = makeSim({ tasks }).seedSteadyState('2026-08-12T00:00Z');
  sim.at('2026-08-12T00:00Z', ({ world }) => { world.mountBehind = true; world.mountBroken = true; });
  sim.run('2026-08-12T00:00Z', '2026-08-12T06:00Z');

  const parked = sim.issues.find((i) => i.labels.has('needs-human'));
  assert.ok(parked, 'the work step failed, so the item parked for a human');

  // The sanctioned re-queue (F7) and nothing else: a human strips the label and
